draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw ancient background
  ctx.fillStyle = '#964B00';
  ctx.fillRect(W/2 - 50, H/2 - 50, 100, 20);

  // draw barley
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // draw fiber
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 20 * Math.sin(t), H/2 + 20 + 20 * Math.cos(t));
  ctx.stroke();

  // draw digestion stick figure
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 10);
  ctx.lineTo(W/2 + 50, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 30, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 70, H/2 + 30);
  ctx.stroke();

  ctx.restore();
}
